import { DISTRICTS, MONTHS, JPTH_SHEET_ID, ISSUE_SHEET_ID, CORS_PROXY, REPORTING_PERIODS } from './constants';
import { ReportRecord, DistrictSummary, ReportingStatus } from './types';

const MONTH_MAP: { [key: string]: number } = {
  'มกราคม': 0, 'กุมภาพันธ์': 1, 'มีนาคม': 2, 'เมษายน': 3, 'พฤษภาคม': 4, 'มิถุนายน': 5,
  'กรกฎาคม': 6, 'สิงหาคม': 7, 'กันยายน': 8, 'ตุลาคม': 9, 'พฤศจิกายน': 10, 'ธันวาคม': 11
};

function parseSheetDate(dateStr: string): string | null {
  if (!dateStr) return null;
  try {
    const parts = dateStr.trim().split(/\s+/);
    const datePart = parts[0];
    const timePart = parts.length > 1 ? parts[1] : '00:00:00';

    if (datePart.includes('/')) {
      const [dayStr, monthStr, yearStr] = datePart.split('/');
      let year = parseInt(yearStr, 10);
      const month = parseInt(monthStr, 10) - 1;
      const day = parseInt(dayStr, 10);
      if (year > 2400) year -= 543;
      const [hourStr, minuteStr, secondStr] = timePart.split(':');
      const hour = parseInt(hourStr || '0', 10);
      const minute = parseInt(minuteStr || '0', 10);
      const second = parseInt(secondStr || '0', 10);
      const dateObj = new Date(year, month, day, hour, minute, second);
      return isNaN(dateObj.getTime()) ? null : dateObj.toISOString();
    }
    const fallback = new Date(dateStr);
    return isNaN(fallback.getTime()) ? null : fallback.toISOString();
  } catch (e) {
    return null;
  }
}

export const isOnTime = (timestamp: string | null, monthName: string, targetYear: number): boolean => {
  if (!timestamp) return false;
  const submitDate = new Date(timestamp);
  const targetMonthIndex = MONTH_MAP[monthName];
  if (targetMonthIndex === undefined) return false;

  // Deadline is 15th of the reporting month
  const deadline = new Date(targetYear, targetMonthIndex, 15, 23, 59, 59);
  return submitDate <= deadline;
};

export const calculateRating = (
  jpthStatus: ReportingStatus,
  jpthOntime: boolean,
  issueStatus: ReportingStatus,
  issueOntime: boolean
): 'A' | 'B' | 'C' | 'D' => {
  const jpthReported = jpthStatus === 'reported';
  const issueReported = issueStatus === 'reported';

  if (jpthReported && issueReported && jpthOntime && issueOntime) {
    return 'A'; // Both reported and both on-time
  } else if (jpthReported && issueReported && (jpthOntime || issueOntime)) {
    return 'B'; // Both reported, at least one on-time
  } else if (jpthReported && issueReported) {
    return 'C'; // Both reported, both late
  } else if ((jpthReported && jpthOntime) || (issueReported && issueOntime)) {
    return 'B'; // Only one reported but it is on-time
  } else {
    return 'D'; // Not reported or incomplete
  }
};

export const getDistrictSummary = (record: ReportRecord): DistrictSummary => {
  const jpthOntime = isOnTime(record.jpth_timestamp, record.month, record.year);
  const issueOntime = isOnTime(record.issue_5plus1_timestamp, record.month, record.year);

  return {
    district_id: record.district_id,
    district_name: record.district_name,
    month: record.month,
    year: record.year,
    jpth_status: record.jpth_status,
    jpth_ontime: jpthOntime,
    issue_status: record.issue_5plus1_status,
    issue_ontime: issueOntime,
    rating: calculateRating(record.jpth_status, jpthOntime, record.issue_5plus1_status, issueOntime)
  };
};

async function fetchCSV(sheetId: string): Promise<string[][]> {
  const url = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`;
  const corsUrl = `${CORS_PROXY}${encodeURIComponent(url)}`;
  try {
    const response = await fetch(corsUrl, { cache: 'no-store' });
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const text = await response.text();
    return parseCSV(text);
  } catch (error) {
    return [];
  }
}

function parseCSV(text: string): string[][] {
  const rows: string[][] = [];
  let currentRow: string[] = [];
  let currentField = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i+1];
    if (inQuotes) {
      if (char === '"' && nextChar === '"') { currentField += '"'; i++; }
      else if (char === '"') inQuotes = false;
      else currentField += char;
    } else {
      if (char === '"') inQuotes = true;
      else if (char === ',') { currentRow.push(currentField); currentField = ''; }
      else if (char === '\n' || char === '\r') {
        currentRow.push(currentField); currentField = '';
        rows.push(currentRow); currentRow = [];
        if (char === '\r' && nextChar === '\n') i++;
      } else currentField += char;
    }
  }
  if (currentField || currentRow.length > 0) { currentRow.push(currentField); rows.push(currentRow); }
  return rows;
}

interface SheetEntry {
  timestamp: string;
  districtId: string;
  month: string;
}

function processSheetData(rows: string[][]): SheetEntry[] {
  if (rows.length < 2) return [];
  const headers = rows[0].map(h => h.trim());
  const timestampIdx = headers.findIndex(h => h.includes('Timestamp') || h.includes('ประทับเวลา'));
  const districtIdx = headers.findIndex(h => h.includes('อำเภอ'));
  const monthIdx = headers.findIndex(h => h.includes('เดือน'));

  const entries: SheetEntry[] = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const timestampStr = row[timestampIdx];
    const timestamp = parseSheetDate(timestampStr);
    if (!timestamp) continue;

    const rawDistrict = row[districtIdx] || '';
    const matchedDistrict = DISTRICTS.find(d => rawDistrict.includes(d.name));
    if (!matchedDistrict) continue;

    const rawMonth = row[monthIdx] || '';
    const foundMonth = MONTHS.find(m => rawMonth.includes(m));
    if (!foundMonth) continue;

    entries.push({ timestamp, districtId: matchedDistrict.id, month: foundMonth });
  }
  return entries;
}

export const fetchData = async (): Promise<ReportRecord[]> => {
  const [jpthRaw, issueRaw] = await Promise.all([
    fetchCSV(JPTH_SHEET_ID),
    fetchCSV(ISSUE_SHEET_ID)
  ]);

  const jpthEntries = processSheetData(jpthRaw);
  const issueEntries = processSheetData(issueRaw);
  const records: ReportRecord[] = [];

  REPORTING_PERIODS.forEach(period => {
    DISTRICTS.forEach(district => {
      const jpthEntry = jpthEntries
        .filter(e => e.districtId === district.id && e.month === period.month)
        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

      const issueEntry = issueEntries
        .filter(e => e.districtId === district.id && e.month === period.month)
        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

      records.push({
        id: `${district.id}-${period.month}-${period.year}`,
        district_id: district.id,
        district_name: district.name,
        month: period.month,
        year: period.year,
        jpth_status: jpthEntry ? 'reported' : 'not_reported',
        jpth_timestamp: jpthEntry ? jpthEntry.timestamp : null,
        issue_5plus1_status: issueEntry ? 'reported' : 'not_reported',
        issue_5plus1_timestamp: issueEntry ? issueEntry.timestamp : null,
      });
    });
  });

  return records;
};

