  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const rawTimestamp = row[timestampIdx];
    const timestamp = parseSheetDate(rawTimestamp);
    if (!timestamp) continue;

    // Robust District Matching
    const rawDistrict = normalizeThai((row[districtIdx] || ''));
    const matchedDistrict = DISTRICTS.find(d => {
        const normName = normalizeThai(d.name);
        return rawDistrict.includes(normName) || normName.includes(rawDistrict);
    });
    if (!matchedDistrict) continue;

    // Robust Month Matching
    const rawMonth = normalizeThai((row[monthIdx] || ''));
    const foundMonth = MONTHS.find(m => rawMonth.includes(normalizeThai(m)));
    if (!foundMonth) continue;

    entries.push({ 
      timestamp, 
      districtId: matchedDistrict.id, 
      monthName: foundMonth 
    });
  }
  return entries;
}

